local Sprite = require(script.Parent.Parent.apis.Sprite)
local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent)

function module:ctor(element)
	self.super.ctor(self, element)
end

function module:SetSprite(group, name)
    local sp
    if typeof(group) == "table" and group.Image and group.ImageRectOffset and group.ImageRectSize then
        sp = group
    else
        sp = Sprite(group, name)
    end

    local img: ImageLabel = self._element
    if sp then
        img.Image = sp.Image
	    img.ImageRectOffset = sp.ImageRectOffset
	    img.ImageRectSize = sp.ImageRectSize
    else
        warn("sprite not found", group, name, img)
    end
end

function module:SetImage(image)
    local img: ImageLabel = self._element
    img.Image = image
    img.ImageRectOffset = Vector2.new(0, 0)
    img.ImageRectSize = Vector2.new(0, 0)
end


return module